"""Section 8 (memory layers) data and static tables, from the agent_memory_layers recordings copied into this folder.

usage: python3 memory_layers/make_memory.py   (from src/; build.sh runs it)
reads  memory_layers/fmem_data.json (the data the Agent memory layers page embedded, built by build_data.py from recordings/)
writes parts/36_js_mem_data.js  (window.HMEM: one changing fact, the gateway, through four stores, session by session)
       parts/20_read_h.html     (static tables: score by ability, evidence, write cost; published numbers)
Every number printed comes from fmem_data.json or from the published sources listed in inputs/research_claims.md.
"""
import json, os, re

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.dirname(HERE)
F = json.load(open(os.path.join(HERE, "fmem_data.json")))
S = F["S"]
GW = re.compile(r"LiteLLM|OpenRouter|gateway", re.I)

# ---- the gateway fact, store by store ----
# steps: sessions where the gateway story moves (index into S), then the question
STEPS = [0, 4, 8, 11]
said = []
for i in STEPS:
    u = [t[1] for t in S[i]["t"] if t[0] == "user"]
    hit = [x for x in u if GW.search(x) or re.search(r"switched the primary model", x)]
    said.append({"s": i, "d": S[i]["d"], "u": hit[0] if hit else u[0]})

# paper loop (Haiku writer): store after each session, the ops of that session
pa = F["PA"]["haiku"]["s"]
paper = []
for i in range(len(S)):
    st = {k: v for k, v in pa[i]["st"].items() if GW.search(v) and not re.search(r"fallback|outage|Presentation", v, re.I)}
    ops = [o for o in pa[i]["ops"] if o.get("id") in st or (o.get("old") and GW.search(o.get("old", "")) and not re.search(r"fallback", o.get("old", ""), re.I))]
    paper.append({"st": st, "ops": ops})

# Mem0 2.2.1 (Haiku writer): every memory with the session that wrote it
mem0 = [{"t": m["t"], "s": m["s"]} for m in F["M0"]["mem"] if GW.search(m["t"]) and not re.search(r"outage|fallback", m["t"], re.I)]

# Graphiti 0.30.2 (Haiku writer): edges with validity windows and this page's judgement of each closure
graph = [e for e in F["GR"]["haiku"]["e"] if GW.search(e["f"]) and not re.search(r"outage|fallback", e["f"], re.I)]

# Letta 0.16.8 (local writer): archival notes and the core block, after each session
lt = F["LT"]["ses"]
letta = []
for i in range(len(S)):
    z = lt[i]
    letta.append({"core": bool(GW.search(z.get("h") or "") or GW.search(z.get("p") or "")),
                  "notes": [a for a in z["a"] if re.search(r"gateway|LiteLLM", a) and not re.search(r"outline", a)]})

q = next(x for x in F["Q"] if x["id"] == "q_gateway_now")
ans = {k: F["A"][k][q["id"]] for k in ("paper_haiku|haiku", "mem0|haiku", "graphiti_haiku|haiku", "letta|local", "full|haiku")}

HMEM = {"steps": said, "paper": paper, "mem0": mem0, "graph": graph, "letta": letta, "dates": [s["d"] for s in S],
        "q": q["q"], "gold": q["g"], "ans": ans}
with open(os.path.join(SRC, "parts", "36_js_mem_data.js"), "w") as f:
    f.write("// generated by src/memory_layers/make_memory.py from memory_layers/fmem_data.json; do not edit\n")
    f.write("window.HMEM=" + json.dumps(HMEM, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/") + ";\n")

# ---- static tables ----
V = F["V"]
TY = [("IE", "Extraction"), ("MS", "Multi-session"), ("KU", "Update"), ("TR", "Temporal"), ("ABS", "Abstention")]
SYS = [("none", "No memory", ""), ("full", "Full history in the prompt", ""), ("mem0", "Mem0 2.2.1 (library)", "Haiku"),
       ("paper_haiku", "Mem0 paper loop", "Haiku"), ("paper_local", "Mem0 paper loop", "local 4B"),
       ("graphiti_haiku", "Graphiti 0.30.2", "Haiku"), ("graphiti_local", "Graphiti 0.30.2", "local 4B"),
       ("letta", "Letta 0.16.8, its own loop", "local 4B"), ("lettastore", "Letta's notes, pasted whole", "local 4B")]
EVK = {"full": "full", "mem0": "mem0", "paper_haiku": "paper_haiku", "paper_local": "paper_local", "graphiti_haiku": "graphiti_haiku",
       "graphiti_local": "graphiti_local", "letta": "letta", "lettastore": "lettastore"}


def by_type(k, r, t):
    a = F["A"].get(k + "|" + r)
    if not a:
        return None
    qs = [x for x in F["Q"] if x["t"] == t]
    return sum(1 for x in qs if a.get(x["id"]) and a[x["id"]][1]), len(qs)


def score(k, r):
    a = F["A"].get(k + "|" + r)
    return (sum(1 for v in a.values() if v[1]), len(a)) if a else None


def cell(v):
    if v is None:
        return '<td class="num mute">n/a</td>'
    a, b = v
    f = a / b
    return f'<td class="num" style="background:color-mix(in srgb,color-mix(in srgb,var(--good) {round(f*100)}%,var(--bad)) 32%,transparent)">{a}/{b}</td>'


rows = []
for k, l, w in SYS:
    r = "local" if k == "letta" else "haiku"
    ev = F["EV"].get(EVK.get(k, ""), None)
    evs = f'{sum(1 for x in ev.values() if x)}/{V["ev.n"]}' if ev else '<span class="mute">n/a</span>'
    sl = score(k, "local")
    wl = w or '<span class="mute">none</span>'
    rows.append(f'<tr><td>{l}</td><td>{wl}</td>' + "".join(cell(by_type(k, r, t)) for t, _ in TY) +
                f'<td class="num"><b>{score(k, r)[0]}/25</b></td><td class="num">{sl[0] if sl else "n/a"}/25</td><td class="num">{evs}</td></tr>')
res = ('<div class="tw"><table class="hc-t hc-mem"><thead><tr><th>Memory</th><th>Writer</th>' + "".join(f'<th class="num">{n}<br><span class="mute" style="font-weight:400">{V["nq."+t]} q</span></th>' for t, n in TY) +
       '<th class="num">All, Haiku reads</th><th class="num">All, 4B reads</th><th class="num">Evidence reached the prompt</th></tr></thead><tbody>' + "".join(rows) + '</tbody></table></div>')

cost_rows = []
lab = {k: (l + (f" ({w})" if w else "")) for k, l, w in SYS}
for c in F["COST"]:
    w = c["w"]
    n = lambda v: "-" if v is None else f"{v:,}"
    cost_rows.append(f'<tr><td>{lab.get(c["k"], c["k"])}</td><td class="num">{n(w["n"]) if w else "0"}</td><td class="num">{n(w["in"]) if w else "-"}</td>'
                     f'<td class="num">{n(w["s"]) if w else "-"}</td><td class="num">{("$%.3f" % w["cost"]) if w and w["cost"] is not None else "local"}</td>'
                     f'<td class="num">{"in-agent" if c["rs"] is None else n(c["rs"])}</td><td class="num">{n(c["ctx"])}</td></tr>')
cost = ('<div class="tw"><table class="hc-t"><thead><tr><th>Memory (writer)</th><th class="num">Write calls, 12 sessions</th><th class="num">Tokens in</th><th class="num">Model time (s)</th>'
        '<th class="num">API-price equivalent</th><th class="num">Search per question (ms)</th><th class="num">Memory text per question (chars)</th></tr></thead><tbody>' + "".join(cost_rows) + '</tbody></table></div>')

M0, ZB, ZI, LB = "https://arxiv.org/abs/2504.19413", "https://www.getzep.com/blog/lies-damn-lies-statistics-is-mem0-really-sota-in-agent-memory/", "https://github.com/getzep/zep-papers/issues/5", "https://www.letta.com/blog/benchmarking-ai-agent-memory/"
ZD, ZP, MG, MAB = "https://www.getzep.com/blog/the-retrieval-tradeoff-what-50-experiments-taught-us-about-context-engineering/", "https://arxiv.org/abs/2501.13956", "https://arxiv.org/abs/2310.08560", "https://arxiv.org/abs/2507.05257"
LME, MD = "https://arxiv.org/abs/2410.10813", "https://docs.mem0.ai/core-concepts/memory-evaluation"
T = [
    ['LOCOMO', 'Full context (baseline)', '72.90', 'b', 'gpt-4o-mini', '28 Apr 2025', M0, 'in Mem0\'s own table, above both Mem0 variants'],
    ['LOCOMO', 'Mem0', '66.88 (Mem0g 68.44)', 'v', 'gpt-4o-mini', '28 Apr 2025', M0, 'paper system (1.x pipeline); 1,764 memory tokens per conversation against 26,031 for full context'],
    ['LOCOMO', 'Zep', '65.99', 'r', 'gpt-4o-mini', '28 Apr 2025', M0, 'run by Mem0'],
    ['LOCOMO', 'Zep', '84 (retracted)', 'v', 'gpt-4o-mini', '6 May 2025', ZB, 'category-5 correct answers counted in the numerator only'],
    ['LOCOMO', 'Zep', '58.44', 'r', 'gpt-4o-mini', '8 May 2025', ZI, 'Mem0\'s rerun with Mem0\'s template'],
    ['LOCOMO', 'Zep', '75.14 &plusmn; 0.17', 'v', 'gpt-4o-mini', '12 May 2025', ZI, '10 runs; Zep corrected the calculation error within a week'],
    ['LOCOMO', 'Letta (file tools)', '74.0', 'v', 'gpt-4o-mini', '12 Aug 2025', LB, 'grep, search_files, open, close over the conversation stored as files'],
    ['LOCOMO', 'Zep', '69.62 to 80.32', 'v', 'gpt-4o-mini (agent and grader)', '9 Dec 2025', ZD, '5 edges / 2 nodes to 30 / 30 retrieved; default 15 / 5 gives 77.06'],
    ['LOCOMO', 'Mem0 platform', '92.5 (old 71.4)', 'v', 'not stated', 'Apr 2026', MD, '"top_200" retrieval; managed platform, "proprietary optimizations not available in the open-source SDK"'],
    ['LongMemEval S', 'Zep', '63.8 vs full context 55.4', 'v', 'gpt-4o-mini', '20 Jan 2025', ZP, '115K-token histories; Zep context 1.6K tokens'],
    ['LongMemEval S', 'Zep', '71.2 vs full context 60.2', 'v', 'gpt-4o', '20 Jan 2025', ZP, 'the "+18.5%" is relative; Zep lower on single-session-assistant (94.6 to 80.4)'],
    ['LongMemEval S', 'GPT-4o, no memory system', '60.6 (87.0 given only the evidence sessions)', 'i', 'gpt-4o', '14 Oct 2024', LME, 'the benchmark paper: "30% to 60%" drops for long-context models'],
    ['LongMemEval', 'Mem0 platform', '94.4 (old 67.8)', 'v', 'not stated', 'Apr 2026', MD, 'top_200 retrieval; managed platform'],
    ['DMR', 'MemGPT', '93.4 (GPT-4 Turbo alone 35.3)', 'v', 'gpt-4-turbo', '12 Oct 2023', MG, 'baseline is a fixed window with recursive summaries; GPT-4: 32.1 against 92.5'],
    ['DMR', 'Zep', '94.8 (MemGPT 93.4, full conversation 94.4)', 'v', 'gpt-4-turbo', '20 Jan 2025', ZP, 'each conversation "easily" fits in the window'],
    ['MemoryAgentBench', 'Mem0 / Zep / MemGPT', '21.1 / 24.0 / 28.3 overall', 'i', 'gpt-4o-mini', 'v4 28 Jun 2026', MAB, 'BM25 41.5, long context 42.2 (Table 3); 2025 product versions, chunked documents'],
    ['AMA-Bench', 'Mem0 / MemGPT', '0.210 / 0.330 average', 'i', 'Qwen-32B', '26 Feb 2026', 'https://arxiv.org/abs/2602.22769', 'agent trajectories, not chat; MemoRAG 0.461 best'],
]
WHO = {"v": "vendor", "r": "rival", "i": "independent", "b": "baseline"}
pub = ('<div class="tw"><table class="hc-t"><thead><tr><th>Benchmark</th><th>System</th><th class="num">Score</th><th>Runner</th><th>Answer model</th><th>Date</th><th>Note</th></tr></thead><tbody>' +
       "".join(f'<tr><td>{b}</td><td>{s}</td><td class="num">{v}</td><td>{WHO[w]}</td><td>{m}</td><td><a href="{u}" target="_blank" rel="noopener noreferrer">{d}</a></td><td>{n}</td></tr>' for b, s, v, w, m, d, u, n in T) +
       '</tbody></table></div>')

html = f"""<!-- generated by src/memory_layers/make_memory.py; do not edit -->
<p><b>The experiment.</b> All three products ran on the same twelve invented sessions between a user, Sam, and an assistant (the parent frameworks root's four sessions extended to twelve; invented, assistant turns are fixed text so every system saw exactly the same history; about {V['full_tokens']} tokens in all, so the full history fits and is an honest upper bound), then answered 25 questions in LongMemEval's five abilities, asked "on" 6 October 2026. Two measurements per answer: did the evidence words reach the prompt (no model needed), and was the answer right (keyword rules per question; an abstention question passes when the answer says it does not know or corrects the false premise; every answer was also read by hand). Writers and readers are Claude Haiku 4.5 and a local Qwen3-4B on Apple M1 Pro. A demonstration of mechanisms, not a benchmark <span class="meas">MEASURED</span>.</p>
{res}
<p class="small mute">Questions right by ability, read by Haiku (Letta's own loop: the local model); "evidence" is out of the {V['ev.n']} questions that have an answer. Recorded 6 Oct 2026: Mem0 2.2.1, Graphiti 0.30.2 on FalkorDB 4.22, the archived Letta 0.16.8 server; the paper loop is the parent frameworks root's minimal ADD/UPDATE/DELETE/NOOP implementation. Scripts and redacted recordings: <code>src/memory_layers/</code>.</p>
<p><b>What the table says.</b> Pasting the whole history scored {V['score.full.haiku']} of 25; the best memory, the paper loop with a Haiku writer, {V['score.pa_haiku.haiku']}; Mem0 2.2.1 {V['score.mem0.haiku']}; Graphiti {V['score.gr_haiku.haiku']}, because only {V['ev.graphiti_haiku']} of {V['ev.n']} answers' evidence reached the prompt; Letta's own loop {V['score.letta.local']}, though its notes pasted whole gave {V['score.lettastore.haiku']}: its write side worked and its read side did not (it searched on {V['lt.searched']} of 25 questions). With no memory at all, {V['score.none.haiku']}. Swap the writer for the 4B model and the same designs lose facts: the paper loop fell to {V['score.pa_local.haiku']} and Graphiti to {V['score.gr_local.haiku']}.</p>
<details class="qa"><summary>What writing the memory cost, per design</summary><div>
{cost}
<p class="small">Claude figures are the CLI's API-price equivalent at Haiku 4.5 list prices; local-model figures are tokens and seconds on a shared M1 Pro, comparable only with each other. Mem0's input is dominated by its extraction prompt ({V['mem0_prompt_tokens']} tokens with the Qwen tokenizer, over the shared local server's limit, which is why the library's writes used Haiku). Graphiti made {V['gr.haiku.calls']} calls for 12 episodes: two is the minimum per episode (entities, then facts), and every new fact that resembles an old one costs another <code>resolve_edge</code> call (26 of them here). Letta has no separate search step: its 25 answers took 36 model calls inside its own loop.</p>
<div class="fm"><div class="eq">break-even sessions &asymp; write cost per session / (history tokens saved per answer &times; answers per session &times; input price)</div>
<p class="small" style="margin:4px 0 0">At this size pasting everything is cheaper than any memory layer for a long time. The vendors' own numbers say the same at their scale: Mem0's paper puts full context at 26,031 tokens per LOCOMO conversation against 1,764 for Mem0, Zep's about 115K against 1.6K on LongMemEval; the saving appears only once history is tens of thousands of tokens and is read many times.</p></div>
</div></details>
<details class="qa"><summary>Every published benchmark number for these products, with its runner</summary><div>
<p>No benchmark was rerun here. LOCOMO (Maharana et al., <a href="https://arxiv.org/abs/2402.17753" target="_blank" rel="noopener noreferrer">arXiv 2402.17753</a>, Feb 2024) is long two-person chats scored by an LLM judge (the "J score"); the paper describes 50 conversations of about 300 turns and 9K tokens, up to 35 sessions; its public release has 10 conversations, 1,986 questions, and 444 of the 446 adversarial questions have no reference answer, so every product evaluation drops that category; it has no knowledge-update questions. LongMemEval (<a href="https://arxiv.org/abs/2410.10813" target="_blank" rel="noopener noreferrer">arXiv 2410.10813</a>, ICLR 2025) has 500 questions over histories of about 115K tokens (setting S) or about 500 sessions and 1.5M tokens (M); counts in the released file: temporal 133, multi-session 133, knowledge update 78, single-session user 70, assistant 56, preference 30, with 30 abstention variants. DMR, MemGPT's test, has 5 short sessions per conversation, which fit in a window. MemoryAgentBench (UCSD, <a href="https://arxiv.org/abs/2507.05257" target="_blank" rel="noopener noreferrer">arXiv 2507.05257</a>) is independent.</p>
{pub}
<p class="small">The same product, Zep, scored 58.44%, 65.99%, 75.14% and up to 80.32% on LOCOMO depending on who configured it, the retrieval template, how many results were retrieved and how one category was counted. Ask five things of any memory benchmark claim: who ran it; does the whole history fit the answer model's window (then full context is the baseline to beat, and it often wins); which answer and judge models; how many memories were retrieved per question; which product version. Sources read 6 Oct 2026, quotes in <code>src/memory_layers/inputs/research_claims.md</code>.</p>
</div></details>
"""
with open(os.path.join(SRC, "parts", "20_read_h.html"), "w") as f:
    f.write(html)
print("wrote 36_js_mem_data.js and 20_read_h.html")
